// Hybrid AI gateway: classify each incoming request, route to Gemini
// ONLY if the content is safe to leave the NAS. Anything clinical /
// TLC / family-private stays here.
//
// Expected request shape:
//   { prompt: "...", category?: "<tag>", system?: "...", model?: "gemini-2.5-pro" }
//
// SAFETY POSTURE: default-deny. Only explicit safe-category tags pass.
// Per CLAUDE.md TLC firewall — clinical/counseling content NEVER leaves
// the NAS. Per family-privacy binding — kids' SMS, Christina's clinical
// data, intimate family conversation NEVER leaves the NAS.

const input = $input.first().json || {};
const body = input.body && typeof input.body === 'object' ? input.body : input;

const prompt = (body.prompt || '').toString();
const category = (body.category || '').toString().toLowerCase().trim();
const system = (body.system || 'You are a helpful, sober, fact-grounded assistant working with the PoeTech Family OS planning corpus. Cite assumptions explicitly. Decline gracefully if data is missing.').toString();
const model = (body.model || 'gemini-2.5-pro').toString();

// Allow-list. Add a category here only after deliberate consideration of
// what data flows through this category.
const SAFE_CATEGORIES = new Set([
  'code-help',         // PWA / n8n / infra code questions, no user data
  'doc-summarize',     // public-facing docs, foundation markdown
  'planning-research', // architecture + roadmap research, no user data
  'public-research',   // general web-research-style questions
  'workflow-design',   // n8n workflow design questions
  'sermon-research'    // public scripture exegesis (no clinical content)
]);

// Always-deny (defensive substring checks against the prompt itself).
const DENY_PATTERNS = [
  /\b(tlc|therapy|counsel|clinical|patient|client session)\b/i,
  /\b(christina'?s clinical|christina'?s patients|tlc therapy)\b/i,
  /\b(child|kids?|christiana|cpoe|mrspoe06)\b.{0,40}\b(diary|journal|private|venting|crying)\b/i,
  /\b(account number|routing number|ssn|social security|password|secret token)\b/i,
  /\b(medical|diagnosis|prescription|prognosis|illness)\b/i
];

let allow = false;
let denyReason = null;

if (!prompt) {
  denyReason = 'empty-prompt';
} else if (!category) {
  denyReason = 'missing-category (default-deny)';
} else if (!SAFE_CATEGORIES.has(category)) {
  denyReason = `category '${category}' not in safe allow-list — add explicit allow if intentional`;
} else {
  // Pattern check on the prompt body itself.
  for (const re of DENY_PATTERNS) {
    if (re.test(prompt)) {
      denyReason = 'prompt content matched a TLC/family-private deny pattern';
      break;
    }
  }
  if (!denyReason) allow = true;
}

return [{
  json: {
    allow,
    deny_reason: denyReason,
    category,
    model,
    system,
    prompt
  }
}];

// Extract the text answer from Gemini's response envelope and log the
// exchange for audit. Persist to /data/gemini-log/ for later review.
const fs = require('fs');
const path = require('path');
const LOG_DIR = '/data/gemini-log';
fs.mkdirSync(LOG_DIR, { recursive: true });

const classified = $('Safety classifier (TLC firewall)').first().json;
const geminiRaw = $input.first().json || {};

let answer = '';
try {
  const cands = geminiRaw.candidates || [];
  const parts = (cands[0] && cands[0].content && cands[0].content.parts) || [];
  answer = parts.map(p => p.text || '').join('').trim();
} catch (_) { answer = ''; }

const record = {
  asked_at: new Date().toISOString(),
  category: classified.category,
  model: classified.model,
  prompt_excerpt: (classified.prompt || '').slice(0, 400),
  answer_excerpt: (answer || '').slice(0, 800),
  raw_response: geminiRaw
};
const safeTs = record.asked_at.replace(/[:.]/g, '-');
try {
  fs.writeFileSync(path.join(LOG_DIR, `${safeTs}__${classified.category || 'unknown'}.json`), JSON.stringify(record, null, 2));
} catch (_) {}

return [{ json: { ok: !!answer, answer, model: classified.model, category: classified.category } }];
